-- DTRMS fictional demo dataset. Import once after the DTRMS schema. Select the destination database first.
-- Demo accounts have an undisclosed random initial password. No mail or notification queue entries are created.
SET SESSION time_zone = '+00:00';
SET NAMES utf8mb4;
START TRANSACTION;
SET @today = DATE(UTC_TIMESTAMP() + INTERVAL 1 HOUR);
SET @week = DATE_SUB(@today, INTERVAL WEEKDAY(@today) DAY);
SET @first = DATE_SUB(@week, INTERVAL 35 DAY);
SET @created = DATE_SUB(@first, INTERVAL 7 DAY);
SET @cutover = (SELECT setting_value FROM system_settings WHERE setting_key='flexible_schedule_start');
SET @demo_hash = 'dtrms-sha384:$2y$12$06o1tChX7CyixAU1gGyqEeS77nwdWzukMuDjWTXt2OX5KeNmEqRzO';
INSERT INTO users(role_id,staff_id,name,email,password_hash,created_at) VALUES ((SELECT id FROM roles WHERE code='hr_manager'),'DEMO-HR','Demo HR Reviewer','demo-hr@example.test',@demo_hash,@created);
SET @reviewer = LAST_INSERT_ID();
INSERT INTO departments(code,name) VALUES ('DEMO-OPS','Demo Operations');
SET @dept = LAST_INSERT_ID();
INSERT INTO users(role_id,department_id,staff_id,name,email,password_hash,created_at) VALUES ((SELECT id FROM roles WHERE code='supervisor'),@dept,'DEMO-OPS-S','Demo Operations Supervisor','demo-ops-s@example.test',@demo_hash,@created);
