INSERT INTO staff_weekly_schedule_days(weekly_schedule_id,scheduled_date) SELECT id,DATE_ADD(@start, INTERVAL days.offset_day DAY) FROM staff_weekly_schedules JOIN (SELECT 1 AS offset_day UNION ALL SELECT 3 AS offset_day UNION ALL SELECT 5 AS offset_day) AS days ON TRUE WHERE user_id=@staff AND week_start=@start;
